import React, { useState, useEffect } from "react";

function MainMenu() {
    const [nextEvent, setNextEvent] = useState(null);
    const [timeLeft, setTimeLeft] = useState({ d: 0, h: 0, m: 0, s: 0, isLive: false });

    // 1. Fetch from your events API
    useEffect(() => {
        fetch("http://localhost:8000/api/events/upcoming") // Using your filtered route
            .then(res => res.json())
            .then(res => {
                console.log(res.data);
                if (res.data && res.data.length > 0) {
                    setNextEvent(res.data[0]); // Picks the closest event (Chennai)
                }
            })
            .catch(err => console.error("Error loading events:", err));
    }, []);

    // 2. Precise Countdown Logic
    useEffect(() => {
        if (!nextEvent) return;

        const timer = setInterval(() => {
            const now = new Date().getTime();
            const start = new Date(nextEvent.start_date).getTime();
            const end = new Date(nextEvent.end_date).getTime();
            const gap = start - now;

            // Check if the event is currently happening
            if (now >= start && now <= end) {
                setTimeLeft(prev => ({ ...prev, isLive: true }));
                return;
            }

            if (gap > 0) {
                setTimeLeft({
                    d: Math.floor(gap / (1000 * 60 * 60 * 24)),
                    h: Math.floor((gap % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60)),
                    m: Math.floor((gap % (1000 * 60 * 60)) / (1000 * 60)),
                    s: Math.floor((gap % (1000 * 60)) / 1000),
                    isLive: false
                });
            }
        }, 1000);

        return () => clearInterval(timer);
    }, [nextEvent]);

    // --- STYLES ---
    const containerStyle = { display: "grid", gridTemplateColumns: "repeat(2, 1fr)", gap: 15, padding: "20px", background: "#F8F9FA", minHeight: "100vh" };
    const itemStyle = { background: "white", padding: 25, borderRadius: 25, color: "#2D3436", boxShadow: "0 4px 12px rgba(0,0,0,0.03)", display: "flex", flexDirection: "column" };

    const heroCard = {
        gridColumn: "span 2",
        background: "linear-gradient(135deg, #A82324 0%, #721112 100%)",
        color: "white",
        padding: "30px",
        borderRadius: 30,
        position: "relative",
        overflow: "hidden",
        boxShadow: "0 15px 35px rgba(168,35,36,0.25)"
    };

    const timeBoxStyle = {
        display: "flex",
        justifyContent: "center",
        gap: "15px",
        margin: "20px 0"
    };

    const unitStyle = {
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        background: "rgba(255,255,255,0.15)",
        padding: "10px",
        borderRadius: "15px",
        minWidth: "60px"
    };

    return (
        <div style={containerStyle}>
            {/* HERO SECTION: COUNTDOWN */}
            <div style={heroCard}>
                {!nextEvent ? (
                    <div style={{ textAlign: "center", padding: "20px" }}>Finding next event...</div>
                ) : (
                    <>

                        <div style={{ display: "flex", justifyContent: "space-between", alignItems: "flex-start" }}>
                            <div style={{ background: "rgba(255,255,255,0.2)", padding: "5px 12px", borderRadius: 20, fontSize: "0.75rem", fontWeight: "bold" }}>
                                {timeLeft.isLive ? "● LIVE NOW" : "UPCOMING EVENT"}
                            </div>
                            <span className="material-icons-round" style={{ opacity: 0.5 }}>notifications_none</span>
                        </div>

                        <div style={timeBoxStyle}>
                            <div style={unitStyle}>
                                <span style={{ fontSize: "1.5rem", fontWeight: "bold" }}>{timeLeft.d}</span>
                                <span style={{ fontSize: "0.6rem", opacity: 0.7 }}>DAYS</span>
                            </div>
                            <div style={unitStyle}>
                                <span style={{ fontSize: "1.5rem", fontWeight: "bold" }}>{timeLeft.h}</span>
                                <span style={{ fontSize: "0.6rem", opacity: 0.7 }}>HRS</span>
                            </div>
                            <div style={unitStyle}>
                                <span style={{ fontSize: "1.5rem", fontWeight: "bold" }}>{timeLeft.m}</span>
                                <span style={{ fontSize: "0.6rem", opacity: 0.7 }}>MINS</span>
                            </div>
                            <div style={unitStyle}>
                                <span style={{ fontSize: "1.5rem", fontWeight: "bold" }}>{timeLeft.s}</span>
                                <span style={{ fontSize: "0.6rem", opacity: 0.7 }}>SECS</span>
                            </div>
                        </div>

                        <h2 style={{ margin: "15px 0 5px 0", fontSize: "1.6rem", fontWeight: "700" }}>{nextEvent.name}</h2>
                        <p style={{ margin: 0, opacity: 0.8, fontSize: "0.85rem", maxWidth: "80%" }}>
                            {nextEvent.venue_details || "Venue to be announced"}
                        </p>
                    </>
                )}
            </div>

            {/* MENU ITEMS */}
            {[
                { label: "Calendar", icon: "calendar_today", color: "#4834d4" },
                { label: "Layout", icon: "grid_view", color: "#eb4d4b" },
                { label: "Events", icon: "event", color: "#6ab04c" },
                { label: "Stats", icon: "insights", color: "#f0932b" },
            ].map((item) => (
                <div key={item.label} style={itemStyle}>
                    <div style={{
                        width: 50, height: 50, borderRadius: 15, display: "flex",
                        alignItems: "center", justifyContent: "center", marginBottom: 15,
                        background: `${item.color}15`, color: item.color
                    }}>
                        <span className="material-icons-round">{item.icon}</span>
                    </div>
                    <div style={{ fontWeight: "bold", fontSize: "1rem" }}>{item.label}</div>
                    <div style={{ fontSize: "0.75rem", color: "#95a5a6", marginTop: 4 }}>Manage {item.label.toLowerCase()}</div>
                </div>
            ))}
        </div>
    );
}

export default MainMenu;
